# Generated by Claudian.
"""Skill: send a message through the native macOS WhatsApp app."""

import re

from ai.response_generator import ResponseGenerator
from automation.whatsapp_automation import send_whatsapp_message
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

# Ordered by specificity — more-specific patterns first.
_PATTERNS = [
    # "send a whatsapp message to John saying Hello"
    (
        re.compile(
            r"(?:send|message|text)\s+(?:a\s+)?(?:whatsapp\s+)?"
            r"(?:message\s+)?to\s+(.+?)\s+(?:saying|that)\s+(.+)"
        ),
        False,  # group order: (contact, message)
    ),
    # "whatsapp John saying Hello"  or  "whatsapp John Hello"
    (re.compile(r"whatsapp\s+(.+?)\s+(?:saying|that)\s+(.+)"), False),
    # "message John saying Hello"
    (re.compile(r"(?:message|text)\s+(.+?)\s+(?:saying|that)\s+(.+)"), False),
    # "tell John on whatsapp Hello"
    (re.compile(r"tell\s+(.+?)\s+(?:on\s+whatsapp\s+)?(?:saying\s+|that\s+)(.+)"), False),
    # "send Hello to John" — only when WhatsApp is mentioned; groups reversed
    (re.compile(r"send\s+(.+?)\s+to\s+(\w+)\s*$"), True),
]


class WhatsAppSendSkill(Skill):
    name = "whatsapp_send"
    description = "Send a WhatsApp message to a contact (via native macOS WhatsApp app)"
    priority = 18

    def __init__(self):
        self._responses = ResponseGenerator()

    def _is_whatsapp_utterance(self, low: str) -> bool:
        """Looser trigger check — the pattern match confirms structure; this
        gate just prevents false positives on unrelated sentences."""
        if "whatsapp" in low:
            return True
        return any(w in low for w in ["message", "text", "msg"]) and any(
            w in low for w in ["saying", " that ", "to "]
        )

    def match(self, text: str) -> SkillMatch | None:
        low = text.lower()
        if not self._is_whatsapp_utterance(low):
            return None
        for pattern, reversed_groups in _PATTERNS:
            m = pattern.search(low)
            if not m:
                continue
            g1, g2 = m.group(1).strip(), m.group(2).strip()
            if reversed_groups:
                contact, message = g2, g1
            else:
                contact, message = g1, g2
            if contact and message:
                return SkillMatch(
                    confidence=0.92,
                    entities={"contact": contact, "message": message},
                )
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        contact = entities.get("contact", "").strip()
        message = entities.get("message", "").strip()
        if not contact or not message:
            return SkillResult(
                text="Who should I message, and what should I say?"
            )
        ok, info = await run_in_thread(send_whatsapp_message, contact, message)
        if ok:
            return SkillResult(text=self._responses.whatsapp_sent(contact))
        return SkillResult(text=self._responses.whatsapp_failed(contact, info))
